{
  "changes": [
    {
      "quote": "{+▪The transactions are dilutive to existing stockholders. The issuance of shares of common stock to the U.S. government at a discount to the current market price is dilutive to existing stockholders, and stockholders may suffer significant additional dilution if the conditions to the warrant are triggered and the warrant is exercised.+}",
      "kind": "substance"
    }
  ],
  "label": "material_added",
  "reason": "A new risk related to dilution of existing stockholders due to the issuance of shares to the U.S. government at a discount and potential warrant exercise has been added."
